const axios = require("axios");

class Listmonk {
    #host;
    #username;
    #password;

    constructor(host, username = "", password = "") {
        this.#host = host;
        this.#username = username;
        this.#password = password
    }

    #request(method, path, parameter = {}) {
        let auth = {};
        if (this.#username.length > 0 && this.#password.length > 0) {
            auth = {
                auth: {
                    username: this.#username,
                    password: this.#password
                }
            }
        }
        switch (method) {
            case 'GET':
                let prameter = new URLSearchParams(parameter);
                return axios.get(`${this.#host}${path}?${prameter.toString()}`, auth);
            case 'POST':
            case 'PUT':
                auth.headers = {
                    'content-type': 'application/json'
                }
                return axios[method.toLowerCase()](`${this.#host}${path}`, parameter, auth)

            default:
                throw `Method ${method} not implemented`
        }
    }

    send_transactional_mail(to, template_id, template_data, content_type = 'html') {
        return this.#request('POST', '/api/tx', {
            'subscriber_email': to,
            'template_id': template_id,
            'content_type': content_type,
            'data': template_data
        })
    }

    get_lists() {
        return this.#request("GET", "/api/lists", {
            'per_page': 'all'
        })
    }

    create_list(name) {
        return this.#request("POST", '/api/lists', {
            name
        })
    }

    create_subscriber(email, name, lists = [], attributes = {}) {
        return this.#request("POST", '/api/subscribers', {
            "email": email,
            "name": name,
            "lists": lists,
            "attribs": attributes
        })
    }

    add_subscribers_to_list(subscriber_ids , lists) {
        return this.#request("PUT", '/api/subscribers/lists', {
            "ids": subscriber_ids,
            "action": "add",
            "target_list_ids": lists,
            "status": "confirmed"
        })
    }

}

module.exports = Listmonk